const D = { energy:.5, density:.6, size:.5, wind:.4, hue:200, sway:.5, x:.5, y:.5, scale:1, speed:1, style:'snow', seed:0, alpha:90 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
