if(sty==='embers'||sty==='stars') blendMode(ADD);
for(let i=0;i<N;i++){
  const dp=fr(i);                 // depth 0 far .. 1 near
  const fall=(0.05+dp*0.22)*(0.5+en)*P.speed;
  const yy=((fr(i+7)+t*fall)%1)*(H+40)-20;
  const drift=Math.sin(t*(0.5+dp)+i)*20*dp*P.sway + wind*dp*120;
